"""Generate Compose paths and SVG deliverables from one original vector source."""
from pathlib import Path
import json, html, argparse
root=Path(__file__).resolve().parents[1]
folder=root/'design/icons'
data=json.loads((folder/'sunny-symbols.json').read_text(encoding='utf-8'))
icons=data['icons']
outputs={}
rows=[]
for name,item in icons.items():
    layers=[]
    for v in item['layers']:
        layers.append('SunnyIconLayer('+json.dumps(v['path'])+', '+str(v['filled']).lower()+', '+str(v['width'])+'f)')
    rows.append('        '+json.dumps(name)+' to listOf('+', '.join(layers)+')')
source='package io.github.xudong7587.sunnytv.feature.ui\n\n// Generated by scripts/generate-sunny-icons.py from design/icons/sunny-symbols.json.\n// Original SunnyTV artwork; no SF Symbols font or Apple vector data is bundled.\ninternal data class SunnyIconLayer(val pathData:String,val filled:Boolean,val strokeWidth:Float)\ninternal object SunnyIconCatalog {\n    const val viewport=24f\n    val icons:Map<String,List<SunnyIconLayer>> = linkedMapOf(\n'+',\n'.join(rows)+'\n    )\n}\n'
outputs[root/'app/src/main/java/io/github/xudong7587/sunnytv/feature/ui/SunnyIconCatalog.kt']=source
cards=[]
symbols=[]
for name,item in icons.items():
    paths=[]
    for v in item['layers']:
        attrs='fill="currentColor"' if v['filled'] else 'fill="none" stroke="currentColor" stroke-width="'+str(v['width'])+'" stroke-linecap="round" stroke-linejoin="round"'
        paths.append('<path d="'+v['path']+'" '+attrs+'/>')
    drawing=''.join(paths)
    svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="24" height="24" role="img"><title>'+html.escape(item['label'])+'</title>'+drawing+'</svg>\n'
    outputs[folder/'svg'/f'{name}.svg']=svg
    symbols.append('<symbol id="'+name+'" viewBox="0 0 24 24">'+drawing+'</symbol>')
    cards.append('<article><div class="sizes"><img class="s20" src="svg/'+name+'.svg" alt=""><img class="s32" src="svg/'+name+'.svg" alt=""><img class="s56" src="svg/'+name+'.svg" alt=""></div><b>'+html.escape(item['label'])+'</b><small>'+name+'</small></article>')
outputs[folder/'sunny-symbols-sprite.svg']='<svg xmlns="http://www.w3.org/2000/svg"><defs>'+''.join(symbols)+'</defs></svg>\n'
outputs[folder/'index.html']='<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SunnyTV Symbols · 矢量图标</title><style>*{box-sizing:border-box}body{margin:0;background:#f5f5f7;color:#1d1d1f;font:15px -apple-system,BlinkMacSystemFont,"Microsoft YaHei",sans-serif}main{max-width:1200px;margin:50px auto;padding:0 30px}h1{font-size:42px;letter-spacing:-1.5px;margin:0 0 14px}header p{color:#6e6e73;line-height:1.8;max-width:850px}.nav-demo{display:flex;gap:26px;align-items:center;width:max-content;padding:15px 28px;background:linear-gradient(110deg,#d8e4ecdd,#e9dfd5cc,#dce8e4dd);border-radius:50px;margin:32px 0 40px;box-shadow:inset 0 1px 1px #fff,0 12px 25px #0001}.nav-demo img{width:27px;height:27px}.nav-demo span{display:flex;align-items:center;gap:12px;font-size:21px}section{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px}article{padding:27px 22px 21px;background:#fff;border-radius:19px;min-width:0}.sizes{height:90px;display:flex;align-items:center;justify-content:space-around;gap:12px}.s20{width:20px;height:20px}.s32{width:32px;height:32px}.s56{width:56px;height:56px}b{display:block;font-weight:550;margin-top:17px}small{display:block;color:#86868b;margin-top:7px;font-size:11px}footer{margin:35px 0;color:#6e6e73;font-size:12px}@media(max-width:750px){section{grid-template-columns:repeat(2,minmax(0,1fr))}main{padding:0 18px}.sizes{gap:8px}article{padding:18px 12px}h1{font-size:32px}.nav-demo{gap:18px;padding-inline:20px}.s56{width:44px;height:44px}}@media(prefers-color-scheme:dark){body{background:#151515;color:#eee}article{background:#232323}.sizes img{filter:invert(1)}.nav-demo{color:#111}}</style></head><body><main><header><h1>SunnyTV Symbols</h1><p>54 个原创矢量图标。播放控制更饱满，导航和工具保留留白；20 /32 /56 像素同时检查。设置采用调节推杆，媒体库采用叠放的媒体卡片。</p></header><div class="nav-demo"><span><img src="svg/home.svg" alt="首页">首页</span><img src="svg/library.svg" alt="媒体库"><img src="svg/search.svg" alt="搜索"><img src="svg/settings.svg" alt="控制台设置"></div><section>'+''.join(cards)+ '</section><footer>同一份路径生成 Android Compose 与 SVG；SVG 使用 currentColor，可任意缩放和换色。</footer></main></body></html>\n'
overview=['<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" viewBox="0 0 1140 1350" width="1140" height="1350"><rect width="1140" height="1350" fill="#f5f5f7"/><defs>'+''.join(symbols)+'</defs><g font-family="Microsoft YaHei,Arial,sans-serif" fill="#1d1d1f"><text x="35" y="58" font-size="32" font-weight="650">SunnyTV Symbols</text><text x="35" y="88" font-size="14" fill="#6e6e73">54 original vectors · navigation and playback</text>']
for index,(name,item) in enumerate(icons.items()):
    x=30+(index%6)*181;y=118+(index//6)*132
    overview.append(f'<rect x="{x}" y="{y}" width="166" height="117" rx="15" fill="#fff"/><use xlink:href="#{name}" x="{x+59}" y="{y+12}" width="48" height="48"/><text x="{x+83}" y="{y+83}" text-anchor="middle" font-size="13">{html.escape(item["label"])}</text><text x="{x+83}" y="{y+103}" text-anchor="middle" font-size="10" fill="#86868b">{name}</text>')
overview.append('</g></svg>\n')
outputs[folder/'sunny-symbols.svg']=''.join(overview)
args=argparse.ArgumentParser();args.add_argument('--check',action='store_true');options=args.parse_args()
if options.check:
    stale=[str(p.relative_to(root)) for p,s in outputs.items() if not p.is_file() or p.read_text(encoding='utf-8')!=s]
    if stale:raise SystemExit('Generated icons are stale: '+', '.join(stale))
else:
    for path,text in outputs.items():
        path.parent.mkdir(parents=True,exist_ok=True)
        path.write_text(text,encoding='utf-8')
print(f'{len(icons)} original symbols; {len(outputs)} generated files verified.' if options.check else f'Generated {len(icons)} original symbols.')
